// Custom Worker entry (architecture section 5, `worker/`). OpenNext generates the fetch handler;
// this file re-uses it and adds the edge fast path (ADR-033), the scheduled handler and the Durable Object classes.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so it does not exist before a build and @ts-expect-error would fail after one.

import { applySecurityHeaders } from "../src/lib/security-headers";
import { runScheduled } from "../src/server/edge/cron";
import { handleAuthed } from "../src/server/edge/authed";
import { handleLegacyRedirect } from "../src/server/edge/legacy-redirects";
import { authedDeps, landingDeps, mutationDeps } from "../src/server/edge/authed-runtime";
import { classify, serveFastPath } from "../src/server/edge/fast-path";
import { handleLanding } from "../src/server/edge/landing";
import { handleMutation } from "../src/server/edge/mutations";
import { EVENTS_PATH, handleEventsPost } from "../src/server/edge/events";
import { handleLeadPost, LEADS_PATH } from "../src/server/edge/leads";
import { serveMedia } from "../src/server/edge/media";
import { handleSignIn } from "../src/server/edge/sign-in";
import { getMediaStore } from "../src/server/media/runtime";

/**
 * The Next.js layer is loaded when a request first needs it (a page miss, a route that is not ours, a signed-in shell miss), not
 * when the Worker instance starts. `.open-next/worker.js` brings the Next.js middleware and its setup, which the lead, event,
 * sign-in and signed-in data requests (the ones with a CPU gate) never use; before this, every fresh instance ran all of it first
 * (Stage 4 CPU repair, tracker Session 21). The handlers with a gate stay imported at the top on purpose: a handler loaded inside
 * its request would put its start-up cost into that request's CPU time, which Workers Free limits to 10 ms.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time (see above)
const loadNext = async () => (await import("../.open-next/worker.js")).default as ExportedHandler<CloudflareEnv>;

type Fetch = (request: Request, env: CloudflareEnv, ctx: ExecutionContext) => Promise<Response>;
const handler = {
  fetch: async (request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> =>
    ((await loadNext()).fetch as unknown as Fetch)(request, env, ctx),
};

/**
 * Free-plan CPU fast path (ADR-033). Workers Free allows about 10 ms of CPU per request and the Next.js server layer
 * alone costs several milliseconds, so the requests that must be cheapest never reach it:
 *  - public pages and content-hashed images are answered from the Cache API (images are read from the public bucket on a miss);
 *  - `POST /api/v1/leads` and `POST /api/v1/events` run as plain functions;
 *  - the two sign-in steps of ours, `/auth/start` and `/auth/return`, are plain functions (`edge/sign-in.ts`);
 *  - the first request after sign-in, `/auth/landing`, is a plain function too (`edge/landing.ts`);
 *  - signed-in screens are a cached shell with no data plus plain data functions (ADR-040, `edge/authed.ts`),
 *    and signed-in changes are `POST /api/v1/<area>/<operation>` plain functions (`edge/mutations.ts`).
 * Everything else, and every page miss, goes to OpenNext unchanged.
 */
async function route(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
  const url = new URL(request.url);
  if (request.method === "POST" && url.pathname === LEADS_PATH) return handleLeadPost(request, env);
  if (request.method === "POST" && url.pathname === EVENTS_PATH) return handleEventsPost(request, env);

  // Old admin addresses that became sections of a hub (architecture 21.5): a tiny map, before any session check, so a bookmark keeps working at no cost.
  const moved = handleLegacyRedirect(request);
  if (moved) return moved;

  const signIn = handleSignIn(request, env);
  if (signIn) return signIn;

  const landing = await handleLanding(request, () => landingDeps(env, (task) => ctx.waitUntil(task)));
  if (landing) return landing;

  const mutation = await handleMutation(request, () => mutationDeps(env));
  if (mutation) return mutation;

  const authed = await handleAuthed(request, () =>
    authedDeps(env, {
      cache: (caches as unknown as { default: Cache }).default,
      next: (shellRequest) => handler.fetch(shellRequest, env, ctx),
      waitUntil: (task) => ctx.waitUntil(task),
    }),
  );
  if (authed) return authed;

  const kind = classify(request.method, url, request.headers.has("cookie"));
  if (!kind) return handler.fetch(request, env, ctx);

  const cache = (caches as unknown as { default: Cache }).default;
  const waitUntil = (task: Promise<unknown>) => ctx.waitUntil(task);
  const next =
    kind === "media"
      ? () => serveMedia({ hashParam: url.pathname.slice("/media/".length), requestUrl: request.url, cache, store: getMediaStore(env), waitUntil })
      : () => handler.fetch(request, env, ctx);
  return serveFastPath(request, kind, { cache, next, waitUntil });
}

/**
 * How many requests this Worker instance has taken, counting this one. The first request of an instance pays the instance's
 * start-up (Cloudflare reports it at every deploy as "Worker Startup Time", about 40 ms for this Worker), so its CPU time is
 * very different from every later request's. The lead endpoint says which one it was in `X-Instance-Request`, so the CPU
 * measurement (scripts/measure-cpu.mjs) can judge warm requests against the gate and report first requests on their own
 * (architecture section 17, tracker Session 21). It identifies no person: it is a counter of this instance's own requests.
 */
let instanceRequests = 0;
const INSTANCE_REQUEST_HEADER = "X-Instance-Request";

export default {
  /**
   * Every response, from the fast paths and from Next.js alike, leaves with the security headers of architecture 13.1
   * (`src/lib/security-headers.ts`). Only headers the response does not already carry are added.
   */
  async fetch(request, env, ctx) {
    const nth = (instanceRequests += 1);
    const response = applySecurityHeaders(await route(request, env, ctx));
    if (request.method !== "POST" || new URL(request.url).pathname !== "/api/v1/leads") return response;
    const marked = new Response(response.body, response);
    marked.headers.set(INSTANCE_REQUEST_HEADER, String(nth));
    return marked;
  },

  /**
   * The Cron Trigger (daily 23:05 UTC, S0.7 and S7.1): records that it ran, rolls the day's anonymous counts and raw tap rows into
   * `event_daily_agg` and purges old raw rows (`src/server/edge/cron.ts`). A failed rollup throws, so the run shows as failed.
   */
  async scheduled(event, env) {
    // Awaited, so a failed rollup (it throws) ends this invocation as failed instead of a promise nobody reads.
    await runScheduled(env, event.scheduledTime);
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Durable Object classes must be exported from the Worker entry. The queue class comes straight from its own small file, not
// through `.open-next/worker.js`, so that file stays unloaded until a page needs it.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time (see above)
export { DOQueueHandler } from "../.open-next/.build/durable-objects/queue.js";
export { Collector } from "./collector";
export { RateLimiter } from "./rate-limiter";
